package ai.eva.android.probe;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;
public class PhoneControlActivity extends ToolPageActivity {
 TextView status;boolean requestedKeep;final Handler stateTimer=new Handler();final Runnable statusTick=new Runnable(){public void run(){refreshStatus();stateTimer.postDelayed(this,1000);}};
 public void onCreate(Bundle b){super.onCreate(b);page("手机控制","");root.removeView(body);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(body,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(getIntent().getBooleanExtra("report-preview",false))new Handler().postDelayed(()->PhoneTaskReport.preview(this),1000);}
 protected void onResume(){super.onResume();PhoneTaskService.restore(this);draw();stateTimer.post(statusTick);}protected void onPause(){stateTimer.removeCallbacks(statusTick);super.onPause();}void refreshStatus(){if(status==null)return;String state=PhoneAccessibility.live==null?"无障碍未连接":PhoneAccessibility.armed?"控制已开启":"控制已停止";String reason=getSharedPreferences("eva-phone",0).getString("reason","");status.setText(state+(PhoneTaskService.keep(this)?" · 保持开启":"")+(reason.isEmpty()?"":"\n"+reason));}
 void draw(){clear();section("连接状态");status=label(PhoneAccessibility.live==null?"无障碍：尚未连接":PhoneAccessibility.armed?"无障碍：已连接 · 控制已开启":"无障碍：已连接 · 控制已停止",14);statusCard(status);body.addView(status);section("控制授权");Switch keepSwitch=new Switch(this);keepSwitch.setText("保持手机控制开启");keepSwitch.setTextColor(ink);keepSwitch.setPadding(0,dp(12),0,dp(12));keepSwitch.setChecked(PhoneTaskService.keep(this));keepSwitch.setOnCheckedChangeListener((v,checked)->{if(checked){requestedKeep=true;requestEnable();}else{PhoneTools.stop(this);draw();}});body.addView(keepSwitch);body.addView(label("开启后记住选择，切换 App 和返回桌面不关闭；服务断开时自动重连；若已授权且运行 Shizuku，会恢复系统无障碍启用项。手动停止会关闭自动恢复。",13));body.addView(label("开启后 Eva 可读取当前页面、截图、点击和输入。任务涉及的页面内容将交给你选择的云端模型。请保持手机解锁；界面操作会使用当前屏幕。",14));body.addView(label(((PowerManager)getSystemService(POWER_SERVICE)).isIgnoringBatteryOptimizations(getPackageName())?"后台保活：已豁免系统电池优化":"后台保活：仍受电池优化限制",13));body.addView(button("后台与电池设置",()->startActivity(new Intent(android.provider.Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS))));body.addView(button("1 · 打开系统无障碍设置",()->startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS))));section("任务反馈");addReportSwitch("任务结束后返回 Eva","returnAfterTask");addReportSwitch("灵动岛显示任务进度","taskPill");section("手动控制");body.addView(button("临时开启手机控制",()->{requestedKeep=false;requestEnable();}));body.addView(button("停止控制",()->{PhoneTools.stop(this);draw();}));section("测试与诊断");body.addView(button("预览任务进度提示",()->PhoneTaskReport.preview(this)));body.addView(button("运行安全测试页",()->startActivity(new Intent(this,PhoneFixtureActivity.class))));body.addView(label(getSharedPreferences("eva-phone-check",0).getString("result",""),12));body.addView(button("测试：打开手机相册",()->{PhoneTools.serial.execute(()->{String message;try{PhoneTools.execute(this,new JSONObject().put("action","open_gallery"));message="已请求打开相册";}catch(Exception e){message=e.getMessage();}final String text=message;runOnUiThread(()->status.setText(text));});}));section("增强能力");body.addView(button("授权 Shizuku / ADB 增强",()->{try{PhoneShell.authorize();}catch(Exception e){status.setText(e.getMessage());}}));body.addView(label(PhoneShell.authorized()?"Shizuku：已授权":"Shizuku：未授权",13));body.addView(label("ADB / Shell 增强：需启动 Shizuku 并单独授权，未授权时不会执行系统命令。\n开启后返回 Eva，新建对话并说明要执行的手机任务。通知栏可随时停止。",13));}
 void addReportSwitch(String title,String key){Switch toggle=new Switch(this);toggle.setText(title);toggle.setTextColor(ink);toggle.setPadding(0,dp(12),0,dp(12));toggle.setChecked(PhoneTaskReport.enabled(this,key));toggle.setOnCheckedChangeListener((v,on)->{getSharedPreferences("eva-phone",0).edit().putBoolean(key,on).apply();if(key.equals("taskPill")&&!on)PhoneTaskReport.close(this);});body.addView(toggle);}
 void requestEnable(){if(PhoneAccessibility.live==null&&!requestedKeep){draw();status.setText("请先在系统无障碍设置中开启 Eva");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=0){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},20);return;}enable();}
 void enable(){try{if(requestedKeep)PhoneTaskService.setKeep(this,true);PhoneAccessibility.generation++;PhoneAccessibility.armed=PhoneAccessibility.live!=null;startForegroundService(new Intent(this,PhoneTaskService.class).setAction("session").putExtra("generation",PhoneAccessibility.generation));PhoneTaskService.reason(this,"");draw();}catch(Exception e){PhoneAccessibility.stopControl();PhoneTaskService.reason(this,"启动失败："+e.getMessage());draw();}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==20){if(g.length>0&&g[0]==0)enable();else{draw();status.setText("请允许通知，以便从通知栏随时停止控制");}}}
 static final class PackageManagerPermission{static final int GRANTED=0;}
}
